\begin{tikzpicture}[font=\sffamily, scale=0.8]
  % vertical cliff face with hatching on its back (left) side
  \draw[very thick] (0,0) -- (0,8);
  \foreach \y in {0.25,0.5,...,7.75} {
    \draw (0,\y) -- (-0.35,\y-0.35);
  }

  % rope fixed at the top of the cliff, running to the climber's hand
  \coordinate (R) at (0,8);
  \coordinate (H) at (3,4.2);
  \coordinate (F) at (0.1,2);
  \draw[thin] (R) -- (H);

  % climber's body, from hand to feet on the cliff
  \draw[very thick] (H) -- (F);
  \fill (H) circle (2pt) node[right] {$H$};
  \fill (F) circle (2pt) node[below right] {$F$};

  % label for the climber
  \draw[thin] (3,4.2) -- (3,1.2);
  \node[below] at (3,1.2) {rock climber};

  % figure caption
  \node[below, font=\sffamily\bfseries] at (1.5,-1.2) {Fig. 2.1};
\end{tikzpicture}
